{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Odanacatib, a methylsulfonylphenyl-containing analogue, had 70% absolute oral bioavailability at 10 mg in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Even at the higher 50 mg fasted dose, odanacatib absolute bioavailability was 30% (90% CI 27–34%), still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Iclepertin, another methylsulfonyl-containing drug, showed 72% absolute oral bioavailability in fasted humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, a heteroaromatic sulfonamide, showed 75% oral bioavailability after a single 100 mg dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pradigastat, a lipophilic biaryl, was completely bioavailable after a 10 mg oral suspension in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Estazolam, a heteroaromatic drug, had 87% oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, especially methylsulfonyl- and heteroaromatic-containing drugs, show absolute oral bioavailability well above 20% (30–90%), so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Dose-dependent or solubility-limited absorption not characterized for the query.",
    "First-pass metabolism of the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

